// Loading node:net is safe even when this command never opens a socket.
// The Rust island exposes the function shape and fences only an actual call.
const net = require("node:net");
const childProcess = require("node:child_process");
const url = require("node:url");
const fs = require("node:fs");
const readline = require("node:readline");
module.exports.name = function name() {
  return [
    typeof net.createServer,
    typeof childProcess.spawn,
    typeof url.fileURLToPath,
    typeof url.pathToFileURL,
    typeof url.fileURLToPath("file:///tmp") === "string",
    typeof fs.fstatSync,
    typeof fs.writeSync,
    typeof readline.createInterface,
  ].join(":");
};
